  border-radius: 0.3em;
  font-weight: 500;
}

pre {
  background-color: var(--color-bg);
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monaco, monospace;
  font-size: 0.8rem;
